{"command":"cd /work && python3 - <<'EOF'
import re, pathlib
d = pathlib.Path('deliverable')
lib = set(re.findall(r'`([a-z_0-9]+\.md)`', open('workspace/library/INDEX.md').read()))
bad = []
for f in ['risk_assessment.json','advice_to_hr.md','corrected_separation_agreement_terms.md','QUESTIONS.md','STATUS.md']:
    t = open(d/f).read()
    for m in re.findall(r'library/([a-z_0-9]+\.md)', t):
        if m not in lib: bad.append((f,m))
    for c in re.findall(r'[Cc]ol\.[^\n]{0,30}|Oubre[^\n]{0,20}|Zubulake[^\n]{0,20}|Breeden[^\n]{0,20}|Burlington[^\n]{0,25}|Faragher[^\n]{0,20}|Ellerth[^\n]{0,20}|§?\s?2\d{3}[^\n]{0,10}|37\(e\)|825\.220[^\n]{0,6}|626\(f\)[^\n]{0,12}|2000e-3[^\n]{0,6}', t):
        pass
print('citable library files:', sorted(lib))
print('invalid library refs:', bad or 'none')
# every distinct statutory/case token used anywhere
toks=set()
for f in ['risk_assessment.json','advice_to_hr.md','corrected_separation_agreement_terms.md','QUESTIONS.md']:
    t=open(d/f).read()
    toks |= set(re.findall(r'29 U\.S\.C\. §?\d+\(?[a-z0-9()]\)?|42 U\.S\.C\. §?[\d\-a-z()]+|Col\. Rev\. Stat\. §?\d+|§+\s?825\.220\(?c?\)?|Fed\. R\. Civ\. P\. 37\(e\)|Oubre|Zubulake|Breeden|Burlington Northern|Burlington Indus|Faragher|Ellerth', t))
print('tokens used:', sorted(toks))
EOF"}
